{"rob": "robolang 1.3;

task deliver_two(robot r, object b1, object b2, location src1, location dst1, location src2, location dst2) {
    goal { object_at b1 dst1; object_at b2 dst2; }
    plan {
        move r to src1;
        grasp r b1;
        move r to dst1;
        place r b1 at dst1;
        move r to src2;
        grasp r b2;
        move r to dst2;
        place r b2 at dst2;
    }
}
